public static String divisibleInRange(int m, int n, int k) {
    String s = "";
    for (int i = m; i <= n; i++) {
        if (i % k == 0) {
            s = s + i + " ";
        }
    }
    return s;
}

public static String digitSumNumbers(int k) {
    String s = "";
    for (int h = 1; h <= 9; h++) {          // ספרת המאות
        for (int t = 0; t <= 9; t++) {      // ספרת העשרות
            int u = k - h - t;              // ספרת האחדות שצריך
            if (u >= 0 && u <= 9) {
                s = s + (h * 100 + t * 10 + u) + " ";
            }
        }
    }
    return s;
}

public static String lowercaseLetters() {
    String s = "";
    for (char c = 'a'; c <= 'z'; c++) {
        s = s + c + " ";
    }
    return s;
}

