public static String check(Object got, Object expected) {
    String g = String.valueOf(got).trim();
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
System.out.println("סעיף א, בדיקה 1 (הדוגמה): " + check(divisibleInRange(10, 30, 7), "14 21 28"));
System.out.println("סעיף א, בדיקה 2 (גם m וגם n מתחלקים): " + check(divisibleInRange(12, 24, 6), "12 18 24"));
System.out.println("סעיף א, בדיקה 3 (אין מספרים כאלה): " + check(divisibleInRange(15, 19, 10), ""));
System.out.println("סעיף א, בדיקה 4 (m שווה ל-n): " + check(divisibleInRange(5, 5, 5), "5"));
System.out.println("סעיף ב, בדיקה 1 (k = 2): " + check(digitSumNumbers(2), "101 110 200"));
System.out.println("סעיף ב, בדיקה 2 (k = 1): " + check(digitSumNumbers(1), "100"));
System.out.println("סעיף ב, בדיקה 3 (k = 26): " + check(digitSumNumbers(26), "899 989 998"));
System.out.println("סעיף ג, בדיקה 1: " + check(lowercaseLetters(), "a b c d e f g h i j k l m n o p q r s t u v w x y z"));

